  long t=1000000;PetState s=new PetState();s.autoSleep=false;eq(s.stage==0,"egg");s.changeField(1);s.hatch(t);s.advance(t+PetState.HOUR);eq(s.cells[1]==4,"field cells");eq(s.hunger==1&&s.energy==88,"baby hunger and energy");eq(s.happy==8,"baby happiness");eq(s.stage==2,"automatic kid");
