  PetState home=new PetState();home.autoSleep=false;home.hatch(t);home.coins=50;home.advance(t+40*PetState.MIN);eq(home.hygiene<100&&home.toilet<100,"independent care needs");eq(home.scrub(home.last)&&home.rinse()&&home.hygiene==100&&!home.rinse(),"soap rinse once");eq(home.bathroom()&&!home.bathroom(),"toilet");eq(home.plant(home.last)&&!home.harvest(home.last),"garden time gate");home.advance(home.last+20*PetState.MIN);eq(home.harvest(home.last)&&!home.harvest(home.last),"garden single reward");home.sick=true;home.germs=3;eq(home.buySupply(0)&&home.medicate()&&!home.sick,"medicine");eq(PetState.decode(home.encode()).encode().equals(home.encode()),"home save");eq(PetState.decode(legacy).hygiene==100,"legacy hygiene default");
  HomeLayout layout=new HomeLayout();eq(layout.hit(135,142,false,1,1)==HomeLayout.BOWL,"home bowl target");eq(layout.hit(30,148,false,1,1)==HomeLayout.BALL,"home ball target");eq(layout.hit(layout.x(false),layout.y(false,1),false,1,1)==HomeLayout.PET,"home pet center");eq(layout.hit(layout.x(true),layout.y(true,1),true,1,1)==HomeLayout.BED,"sleep touch target");try{String coords="rug=81,160\nbed_anchor=36,105\nbed=5,50,60,115\nbowl=125,128,151,146\nball=15,143,32,159\nlab=115,18,145,58\nconsole=4,122,20,136\n";HomeLayout projected=HomeLayout.read(new java.io.ByteArrayInputStream(coords.getBytes(java.nio.charset.StandardCharsets.UTF_8)));eq(projected.hit(139,137,false,1,1)==HomeLayout.BOWL,"projected bowl");}catch(java.io.IOException e){throw new AssertionError(e);}
